import{_ as i,o as a,c as n,ag as l}from"./chunks/framework.PVHj0As1.js";const e="/pub-blog/assets/image.KT_SVOeD.png",h="/pub-blog/assets/image-20250826191034850.BOg4pICA.png",t="/pub-blog/assets/image-20250826191107096.DGcLuZcH.png",p="/pub-blog/assets/image-20250822223258675.CJHnmYEl.png",k="/pub-blog/assets/wanshaoweixin.DWzIcicW.jpg",m=JSON.parse("{\"title\":\"可可图片编辑 HarmonyOS（3）应用间分享图片\",\"description\":\"\",\"frontmatter\":{},\"headers\":[],\"relativePath\":\"鸿蒙开发技巧/可可图片编辑/可可图片编辑 HarmonyOS（3）分享图片/可可图片编辑 HarmonyOS（3）分享图片.md\",\"filePath\":\"鸿蒙开发技巧/可可图片编辑/可可图片编辑 HarmonyOS（3）分享图片/可可图片编辑 HarmonyOS（3）分享图片.md\",\"lastUpdated\":1757677612000,\"__rawMarkdown\":\"# 可可图片编辑 HarmonyOS（3）应用间分享图片\\n\\n## 前言\\n\\n**可可图标编辑**也实现了图片的分享功能，演示效果如下。\\n\\n![](assets/image.png)\\n\\n\\n\\n## Share Kit（分享服务） 介绍\\n\\nhare Kit（分享服务）为应用提供文本、图片、视频等内容跨应用、跨端分享能力。\\n\\n应用把需要分享的内容和预览样式配置给Share Kit，Share Kit将根据不同的场景进行使用：\\n\\n- 针对应用间分享的场景，根据分享的数据类型、数量等信息构建分享面板，为用户提供内容预览、推荐分享联系人、关联应用及操作界面，便于用户快速选择分享应用或操作，将内容分发到目标应用。\\n- 针对跨端分享的场景，根据分享的数据类型、数量等信息构建预览界面，用于跨端分享。\\n\\n| 应用类型 | 相关逻辑                                                     |\\n| :------- | :----------------------------------------------------------- |\\n| 宿主应用 | 宿主应用需要对可分享的内容提供分享入口，在用户点击分享时，配置分享内容到分享，拉起系统分享面板。[通过分享面板发起分享](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/share-mobilephone-app-share)[碰一碰分享](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/knock-share) |\\n| 目标应用 | 需要在应用中构建具有数据处理能力组件，包括以下两种分享方式。[应用内处理分享内容](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/share-interface-description)[分享详情页处理分享内容](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/share-sec-panel)（可选）社交类应用可遵照[意图框架](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/intents-introduction)接入规范把最近分享行为联系人相关信息捐献到[意图框架](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/intents-introduction)，Share Kit可从[意图框架](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/intents-introduction)获取推荐信息，当用户选择推荐的联系人时，会把联系人信息随分享数据一起给到目标应用，目标应用可以根据联系人信息直接一步发送内容给指定用户。 |\\n\\n### 分类\\n\\nShare Kit 可以分为 systemShare 和 HarmonyShare ，两者区别主要是：\\n\\n- systemShare 用于应用之间的分享\\n- HarmonyShare  用于设备之间的分享\\n\\n在实际开发中，两者可能配合使用：\\n\\n跨端分享：通过 HarmonyShare 发起碰一碰传输，接收端通过 HarmonyShare 的沙箱监听处理数据。  \\n\\n应用内分享：通过 systemShare 构造分享内容，用户选择目标应用后跳转到对应页面。\\n\\n\\n\\n\\n\\n## systemShare  使用步骤\\n\\n\\n\\n![image-20250826191034850](assets/image-20250826191034850.png)\\n\\n![image-20250826191107096](assets/image-20250826191107096.png)\\n\\n### 1. 选择图片\\n\\n1. **配置图片选择参数**\\n   - 创建 `PhotoSelectOptions` 对象，设置 `MIMEType` 为 `IMAGE_TYPE` 限制只能选择图片类型文件\\n   - 通过 `maxSelectNumber = 5` 限制最大可选择数量，符合鸿蒙系统图片选择器的多选能力\\n2. **创建图片选择器实例**\\n   - 使用 `PhotoViewPicker` 类（鸿蒙媒体访问框架）创建选择器实例，体现鸿蒙API的分层设计\\n3. **调用异步选择方法**\\n   - 通过 `select()`方法触发系统图片选择界面，采用Promise异步处理机制：\\n     - **成功回调**：提取返回结果中的 `photoUris` 数组，取首元素赋值给组件状态变量 `fileUri`，并打印完整URI列表\\n     - **异常处理**：捕获 `BusinessError` 异常，输出包含错误码和消息的日志，符合ArkTS错误处理规范\\n\\n```typescript\\n      Button(\\\"选择图片\\\")\\n        .onClick(() => {\\n          // 1 设置选择图片的参数\\n          const photoSelectOptions = new photoAccessHelper.PhotoSelectOptions();\\n          photoSelectOptions.MIMEType = photoAccessHelper.PhotoViewMIMETypes.IMAGE_TYPE; // 过滤选择媒体文件类型为IMAGE。\\n          photoSelectOptions.maxSelectNumber = 5; // 选择媒体文件的最大数目。\\n\\n          let uris: Array<string> = [];\\n          // 2 创建图片选择器\\n          const photoViewPicker = new photoAccessHelper.PhotoViewPicker();\\n          // 3 开始选择图片\\n          photoViewPicker.select(photoSelectOptions).then((photoSelectResult: photoAccessHelper.PhotoSelectResult) => {\\n            uris = photoSelectResult.photoUris;\\n            this.fileUri = uris[0]\\n            console.info('photoViewPicker.select to file succeed and uris are:' + uris);\\n          }).catch((err: BusinessError) => {\\n            console.error(`Invoke photoViewPicker.select failed, code is ${err.code}, message is ${err.message}`);\\n          })\\n        })\\n```\\n\\n\\n\\n### 2. 拷贝到沙箱\\n\\n1. **获取沙箱路径**\\n   - 通过 `getUIContext().getHostContext()` 获取 UIAbility 上下文\\n   - 使用 `cacheDir` 属性获取应用专属缓存目录（框架提供的安全存储路径）\\n2. **生成唯一文件名**\\n   - 通过 `split('.').pop()` 解析原始文件的扩展名（ArkTS 的字符串操作特性）\\n   - 使用 `Date.now()` 生成时间戳作为文件名前缀，确保文件名唯一性\\n3. **执行文件拷贝**\\n   - 使用 `fs.openSync` 以只读模式打开源文件（ArkTS 文件系统 API）\\n   - 调用 `fs.copyFileSync` 执行文件描述符到目标路径的同步拷贝操作\\n4. **状态反馈**\\n   - 成功时通过 `AlertDialog` 显示操作结果（ArkUI 的声明式 UI 组件）\\n   - 失败时捕获异常并显示错误提示（try-catch 异常处理机制）\\n5. **数据绑定更新**\\n   - 将生成的缓存路径 `copyFilePath` 赋值给 `this.cacheUri`，用于后续数据绑定或状态管理（响应式编程特性）\\n\\n```typescript\\nButton(\\\"复制到沙箱\\\")\\n.onClick(async () => {\\n\\n  try {\\n    const context = this.getUIContext().getHostContext() as common.UIAbilityContext;\\n    const cacheDir = context.cacheDir;\\n    const fileType = this.fileUri.split('.').pop() // 后缀名\\n    // 生成一个新的文件名\\n    const fileName = Date.now() + '.' + fileType\\n    // 通过缓存路径+文件名 拼接出完整的路径\\n    const copyFilePath = cacheDir + '/' + fileName\\n    // 将文件 拷贝到 临时目录\\n    const file = fs.openSync(this.fileUri, fs.OpenMode.READ_ONLY)\\n    fs.copyFileSync(file.fd, copyFilePath)\\n    AlertDialog.show({ message: JSON.stringify('写入到沙箱', null, 2) })\\n    this.cacheUri = copyFilePath\\n  } catch (e) {\\n    AlertDialog.show({ message: JSON.stringify('写入失败', null, 2) })\\n  }\\n\\n})\\n```\\n\\n\\n\\n### 3. 分享\\n\\n1. **获取UI上下文**\\n\\n   - 通过`this.getUIContext()`获取当前UI组件的上下文对象\\n   - 使用`getHostContext()`获取UIAbility上下文，用于后续调用系统分享能力\\n\\n2. **确定统一数据类型(UTD)**\\n\\n   - 通过文件后缀名(jpg/png/webp)匹配对应的UTD类型ID\\n   - 使用`utd.getUniformDataTypeByFilenameExtension`API获取标准数据类型标识\\n\\n3. **构建分享数据对象**\\n\\n   创建 `systemShare.SharedData`实例，包含：\\n\\n   - utd：统一数据类型标识\\n   - title/description：分享时显示的元数据\\n   - uri：通过`fileUri.getUriFromPath`转换沙箱路径为可访问URI\\n\\n4. **初始化分享控制器**\\n\\n   创建`systemShare.ShareController`实例，绑定分享数据\\n\\n5. **显示系统分享界面**\\n\\n   调用 `controller.show()`步方法，传入：\\n\\n   - SelectionMode.SINGLE：单选模式\\n   - SharePreviewMode.DETAIL：详细预览模式\\n\\n```typescript\\nButton(\\\"分享\\\")\\n.onClick(async () => {\\n  try { // 获取UI上下文\\n    const uiContext: UIContext = this.getUIContext();\\n    const context: common.UIAbilityContext = uiContext.getHostContext() as common.UIAbilityContext;\\n\\n\\n    // 根据图片格式确定UTD类型\\n    let utdTypeId: string;\\n    switch (this.fileUri.split('.').pop()) {\\n      case 'jpeg':\\n      case 'jpg':\\n        utdTypeId = utd.getUniformDataTypeByFilenameExtension('.jpg', utd.UniformDataType.IMAGE);\\n        break;\\n      case 'png':\\n        utdTypeId = utd.getUniformDataTypeByFilenameExtension('.png', utd.UniformDataType.IMAGE);\\n        break;\\n      case 'webp':\\n        utdTypeId = utd.getUniformDataTypeByFilenameExtension('.webp', utd.UniformDataType.IMAGE);\\n        break;\\n      default:\\n        utdTypeId = utd.getUniformDataTypeByFilenameExtension('.jpg', utd.UniformDataType.IMAGE);\\n    }\\n\\n\\n    // 创建分享数据，使用沙箱中的图片URI\\n    const shareData: systemShare.SharedData = new systemShare.SharedData({\\n      utd: utdTypeId,\\n      title: 'Picture Title',\\n      description: 'Picture Description',\\n      uri: fileUri.getUriFromPath(this.cacheUri),\\n    });\\n\\n    // 创建分享控制器\\n    const controller: systemShare.ShareController = new systemShare.ShareController(shareData);\\n\\n    // 显示分享界面\\n    await controller.show(context, {\\n\\n      selectionMode: systemShare.SelectionMode.SINGLE,\\n      previewMode: systemShare.SharePreviewMode.DETAIL\\n    });\\n\\n    console.log('图片分享成功');\\n  } catch (e) {\\n    console.log('图片分享失败');\\n  }\\n})\\n```\\n\\n## 总结\\n\\n本文介绍了在鸿蒙应用中实现图片分享功能的完整流程。通过 Share Kit 的 systemShare 服务，开发者可以轻松实现应用间的图片分享。核心实现包括三个步骤：\\n\\n1. **图片选择**：使用 `PhotoViewPicker` 调用系统图片选择器，支持多选并限制文件类型\\n2. **沙箱拷贝**：将选中图片拷贝到应用缓存目录，确保分享时的文件访问权限\\n3. **分享操作**：通过 `ShareController` 构建分享数据，调用系统分享面板完成跨应用分享\\n\\n整个流程充分利用了鸿蒙系统的媒体访问框架、文件系统 API 和分享服务，为用户提供了原生、流畅的图片分享体验。\\n\\n\\n\\n\\n\\n## 案例完整代码\\n\\n```typescript\\nimport { photoAccessHelper } from '@kit.MediaLibraryKit';\\nimport { BusinessError } from '@kit.BasicServicesKit';\\nimport { fileUri, fileIo as fs } from '@kit.CoreFileKit';\\nimport { common } from '@kit.AbilityKit';\\nimport { uniformTypeDescriptor as utd } from '@kit.ArkData';\\nimport { systemShare } from '@kit.ShareKit';\\n\\n@ComponentV2\\n@Entry\\nstruct Index {\\n  fileUri: string = \\\"\\\"\\n  cacheUri: string = \\\"\\\"\\n\\n  build() {\\n    Column({ space: 10 }) {\\n      Button(\\\"选择图片\\\")\\n        .onClick(() => {\\n          // 1 设置选择图片的参数\\n          const photoSelectOptions = new photoAccessHelper.PhotoSelectOptions();\\n          photoSelectOptions.MIMEType = photoAccessHelper.PhotoViewMIMETypes.IMAGE_TYPE; // 过滤选择媒体文件类型为IMAGE。\\n          photoSelectOptions.maxSelectNumber = 5; // 选择媒体文件的最大数目。\\n\\n          let uris: Array<string> = [];\\n          // 2 创建图片选择器\\n          const photoViewPicker = new photoAccessHelper.PhotoViewPicker();\\n          // 3 开始选择图片\\n          photoViewPicker.select(photoSelectOptions).then((photoSelectResult: photoAccessHelper.PhotoSelectResult) => {\\n            uris = photoSelectResult.photoUris;\\n            this.fileUri = uris[0]\\n            console.info('photoViewPicker.select to file succeed and uris are:' + uris);\\n          }).catch((err: BusinessError) => {\\n            console.error(`Invoke photoViewPicker.select failed, code is ${err.code}, message is ${err.message}`);\\n          })\\n        })\\n\\n      Button(\\\"复制到沙箱\\\")\\n        .onClick(async () => {\\n\\n          try {\\n            const context = this.getUIContext().getHostContext() as common.UIAbilityContext;\\n            const cacheDir = context.cacheDir;\\n            const fileType = this.fileUri.split('.').pop() // 后缀名\\n            // 生成一个新的文件名\\n            const fileName = Date.now() + '.' + fileType\\n            // 通过缓存路径+文件名 拼接出完整的路径\\n            const copyFilePath = cacheDir + '/' + fileName\\n            // 将文件 拷贝到 临时目录\\n            const file = fs.openSync(this.fileUri, fs.OpenMode.READ_ONLY)\\n            fs.copyFileSync(file.fd, copyFilePath)\\n            AlertDialog.show({ message: JSON.stringify('写入到沙箱', null, 2) })\\n            this.cacheUri = copyFilePath\\n          } catch (e) {\\n            AlertDialog.show({ message: JSON.stringify('写入失败', null, 2) })\\n          }\\n\\n        })\\n\\n      Button(\\\"分享\\\")\\n        .onClick(async () => {\\n          try { // 获取UI上下文\\n            const uiContext: UIContext = this.getUIContext();\\n            const context: common.UIAbilityContext = uiContext.getHostContext() as common.UIAbilityContext;\\n\\n\\n            // 根据图片格式确定UTD类型\\n            let utdTypeId: string;\\n            switch (this.fileUri.split('.').pop()) {\\n              case 'jpeg':\\n              case 'jpg':\\n                utdTypeId = utd.getUniformDataTypeByFilenameExtension('.jpg', utd.UniformDataType.IMAGE);\\n                break;\\n              case 'png':\\n                utdTypeId = utd.getUniformDataTypeByFilenameExtension('.png', utd.UniformDataType.IMAGE);\\n                break;\\n              case 'webp':\\n                utdTypeId = utd.getUniformDataTypeByFilenameExtension('.webp', utd.UniformDataType.IMAGE);\\n                break;\\n              default:\\n                utdTypeId = utd.getUniformDataTypeByFilenameExtension('.jpg', utd.UniformDataType.IMAGE);\\n            }\\n\\n\\n            // 创建分享数据，使用沙箱中的图片URI\\n            const shareData: systemShare.SharedData = new systemShare.SharedData({\\n              utd: utdTypeId,\\n              title: 'Picture Title',\\n              description: 'Picture Description',\\n              uri: fileUri.getUriFromPath(this.cacheUri),\\n            });\\n\\n            // 创建分享控制器\\n            const controller: systemShare.ShareController = new systemShare.ShareController(shareData);\\n\\n            // 显示分享界面\\n            await controller.show(context, {\\n      \\n              selectionMode: systemShare.SelectionMode.SINGLE,\\n              previewMode: systemShare.SharePreviewMode.DETAIL\\n            });\\n\\n            console.log('图片分享成功');\\n          } catch (e) {\\n            console.log('图片分享失败');\\n          }\\n        })\\n\\n\\n    }\\n    .width(\\\"100%\\\")\\n    .height(\\\"100%\\\")\\n    .justifyContent(FlexAlign.Center)\\n  }\\n}\\n```\\n\\n\\n\\n## 以往文章\\n\\n\\n\\n- [可可图片编辑 HarmonyOS 上架应用分享](https://mp.weixin.qq.com/s?__biz=MzI0NjY1MDY3Mg==&mid=2247489342&idx=1&sn=15f4872e080ee3f86efdc32d6edfd979&chksm=e813ff241c45844ae10e1fb352499b7253ae91ad932db71f17e86fa2251bb17251d5d840d1ab&scene=126&sessionid=1756092287&subscene=91&clicktime=1756092289&enterid=1756092289#rd)\\n- [可可图片编辑 HarmonyOS（2） 选择图片和保存到图库](https://mp.weixin.qq.com/s/dacDD763JhrLkIS1V8rrdg)\\n- [懂你的HarmonyOS知识库更新了，已经来到10970个文档了](https://mp.weixin.qq.com/s/sMd0CGe54T2Eya8dPaEn2A)\\n- [AI编程神器！Trae+Claude4.0 简单配置 让 HarmonyOS 开发效率飙升](https://mp.weixin.qq.com/s/AsieJTX8RkixgaKyDrzddg)\\n\\n\\n\\n\\n\\n## 近期活动\\n\\n最近想要想要考取 HarmonyOS 基础或者高级证书，或者快要获取的同学都可以点击这个链接，[加入我的班级](https://developer.huawei.com/consumer/cn/training/classDetail/7e230b074eaa41c587c71c1d1a9a6514?type=1%3Fha_source%3Dhmosclass&ha_sourceId=89000248)，考取成功有机会获得鸿蒙礼盒一份。\\n\\n![image-20250822223258675](assets/image-20250822223258675.png)\\n\\n\\n\\n## 联系我\\n\\n可以加我微信，带你了解更多HarmonyOS相关的资讯。\\n\\n![wanshaoweixin](assets/wanshaoweixin.jpg)\"}"),r={name:"鸿蒙开发技巧/可可图片编辑/可可图片编辑 HarmonyOS（3）分享图片/可可图片编辑 HarmonyOS（3）分享图片.md"};function E(d,s,y,g,o,c){return a(),n("div",null,[...s[0]||(s[0]=[l("",41)])])}const u=i(r,[["render",E]]);export{m as __pageData,u as default};
